<section data-page-title="Billing History" data-page-script="billing_history.js"><div class="page-intro"><span class="eyebrow">Invoices</span><h2>Billing history</h2><p>View all invoices, paid status, discounts, and receipt information.</p></div><div id="alertBox" class="alert"></div><div class="card"><div class="toolbar"><input class="input" id="searchInput" placeholder="Search booking ID or payment status"><select class="select" id="paymentFilter"><option value="">All Payments</option><option value="pending">Pending</option><option value="paid">Paid</option></select><button class="btn btn-light" id="refreshBtn">Refresh</button></div><div class="table-wrap"><table><thead><tr><th>Booking</th><th>Room</th><th>Base</th><th>Extras</th><th>Discount</th><th>Total</th><th>Status</th><th>Paid At</th></tr></thead><tbody id="billingTable"><tr><td colspan="8" class="empty">Loading bills...</td></tr></tbody></table></div></div></section>